-- Attach a remote database over the worker (spawned via stdio here).
ATTACH 'adbc' AS pg (
    TYPE vgi,
    LOCATION '/path/to/vgi-adbc/bin/vgi-adbc-worker',
    driver 'postgresql',
    uri 'postgresql://user:pw@localhost:5432/mydb'
);

-- Query it as if it were local — the WHERE and the column list are pushed to Postgres.
SELECT id, name FROM pg.public.events WHERE id > 100 ORDER BY id;
SELECT count(*) FROM pg.public.events;

-- SQLite works the same way (the ADBC SQLite driver embeds SQLite; no server needed).
ATTACH 'adbc' AS sl (TYPE vgi, LOCATION '…/bin/vgi-adbc-worker',
                     driver 'sqlite', uri '/data/app.sqlite');
SELECT * FROM sl.main.orders;

DETACH pg;

INSTALL spatial; LOAD spatial;
ATTACH 'arcgis' AS va (TYPE vgi, LOCATION '/abs/path/to/vgi-arcgis-worker',
                       url 'https://vginmaps.vdem.virginia.gov/arcgis/rest/services');

SELECT LOCALITY, count(*)
FROM va.va_base_layers_va_parcels.virginia_parcels
WHERE FIPS = '51580'          -- runs on the ArcGIS server
GROUP BY ALL;

LOAD vgi;
ATTACH 'asn1' (TYPE vgi, LOCATION 'github-auto://Query-farm/vgi-asn1@v0.2.1');
SET search_path = 'asn1.main';

-- Decode any BER/DER blob to JSON, to self-describing JSON, and to a dump.
SELECT decode(from_hex('3003020105'));                 -- '[5]'
SELECT to_json(payload), dump(payload) FROM read_blob('s3://pki/*.der');

-- Resolve OIDs and inventory every OID in a blob.
SELECT oid_name('1.2.840.113549.1.1.11');              -- 'sha256WithRSAEncryption'
SELECT oids(data) FROM blobs;                          -- LIST<STRUCT(oid,name,path)>

-- Robust, verify-free triage: well-formedness with a classified failure kind.
SELECT well_formed(data) FROM unknown_blobs WHERE NOT (well_formed(data)).ok;

-- Shred a CMS SignedData and join embedded signer certs to vgi-x509.
SELECT s.digest_alg, s.sig_alg, s.signing_time, s.signer_cert_sha256
FROM asn1.main.cms_signers(read_blob('codesign.p7s')) s;

