INSTALL vgi FROM community;
LOAD vgi;

ATTACH 'bluesky' (TYPE vgi,
  LOCATION 'uvx --from git+https://github.com/Query-farm/vgi-bluesky vgi-bluesky');

-- What's trending right now
SELECT rank, display_name, category, post_count FROM bluesky.trends ORDER BY rank;

-- Accounts about DuckDB, ranked by audience
SELECT p.handle, p.followers_count
FROM (SELECT did FROM bluesky.search_actors('duckdb') LIMIT 20) a,
     LATERAL bluesky.profile(a.did) p
ORDER BY p.followers_count DESC;

-- Ten seconds of the whole network, by record type
SELECT collection, count(*) AS events
FROM bluesky.jetstream()
GROUP BY ALL ORDER BY events DESC;

INSTALL vgi FROM community;
LOAD vgi;

ATTACH 'bson' AS bson (TYPE vgi, LOCATION 'github-auto://Query-farm/vgi-bson@v0.2.1');

-- Render a BSON document as canonical (lossless) Extended JSON v2.
SELECT bson.main.to_json(bson.main.from_json('{"a":1}'));

-- Render the same document as relaxed, human-readable Extended JSON.
SELECT bson.main.to_json(bson.main.from_json('{"a":1}'), 'relaxed');

INSTALL vgi FROM community; LOAD vgi;
ATTACH 'cal' (TYPE vgi, LOCATION 'uvx --from git+https://github.com/Query-farm/vgi-calendar@v0.2.0 vgi-calendar-worker');

SELECT cal.easter(2026);                                  -- DATE 2026-04-05
SELECT cal.iso_year_week(DATE '2026-06-22');              -- '2026-W26'
SELECT cal.is_holiday(DATE '2026-12-25');                 -- true (country defaults to 'US')
SELECT cal.is_holiday(DATE '2026-07-14', 'FR');           -- true (Bastille Day)
SELECT * FROM cal.holidays(2026, country := 'DE', subdiv := 'BY');  -- Bavaria
SELECT * FROM cal.rrule(TIMESTAMP '2026-01-01', 'FREQ=WEEKLY;COUNT=4');

INSTALL vgi FROM community; LOAD vgi;
ATTACH 'causal' (TYPE vgi, LOCATION 'uvx --from git+https://github.com/Query-farm/vgi-causal@v0.2.0 vgi-causal-worker');

-- Average Treatment Effect: one row per estimator (ipw, regression_adjustment, aipw)
SELECT * FROM causal.ate((SELECT * FROM cohort),
                         treatment := 't', outcome := 'y');

-- Per-row propensity scores e(X) = P(T=1 | X); id is carried through
SELECT * FROM causal.propensity_scores((SELECT id, t, x1, x2 FROM cohort),
                                       treatment := 't', id := 'id')
ORDER BY id;

-- Average Treatment effect on the Treated
SELECT * FROM causal.att((SELECT * FROM cohort),
                         treatment := 't', outcome := 'y');

INSTALL vgi FROM community;
LOAD vgi;
ATTACH 'cbor' (TYPE vgi, LOCATION 'github-auto://Query-farm/vgi-cbor@v0.5.1');
SET search_path = 'memory.main,cbor.main';

SELECT to_json(from_hex('83010203'));        -- [1,2,3]
SELECT diagnostic(from_hex('c11a514b67b0')); -- 1(1363896240)

INSTALL vgi FROM community; LOAD vgi;
ATTACH 'chart' (TYPE vgi, LOCATION 'java -jar vgi-chart-v0.2.0.jar');

-- a line chart of (x, y) points -> one PNG BLOB row
SELECT png
FROM chart.chart_line((SELECT x, y FROM points), x := 'x', y := 'y');

-- a bar chart with a custom title and size
SELECT octet_length(png)
FROM chart.chart_bar((SELECT category, total FROM sales),
                     category := 'category', value := 'total',
                     title := 'Sales by region', width := 1000, height := 700);

-- a series-grouped line chart (one line per `series` value)
SELECT png
FROM chart.chart_line((SELECT day, amount, region FROM ts),
                      x := 'day', y := 'amount', series := 'region');

LOAD vgi;
ATTACH 'code' (TYPE vgi, LOCATION 'github-auto://Query-farm/vgi-code@v0.2.0');
SET search_path = 'code.main';

-- Infer a language from a filename.
SELECT language_of('main.rs');                 -- → 'rust'

-- Per-row analysis of a source column.
SELECT path,
       count_functions(content, language_of(path)) AS fns,
       loc(content, language_of(path))            AS code_lines
FROM files;

-- One import per row.
SELECT UNNEST(extract_imports(content, 'python')) FROM files;

-- The power feature: run any tree-sitter query.
SELECT UNNEST(ts_query(content, 'rust',
       '(function_item name: (identifier) @n)')) FROM files;

-- Structural symbols of one document (table function).
SELECT * FROM symbols('fn add(a:i32,b:i32)->i32{a+b}', 'rust');
-- kind     | name | start_line | end_line
-- function | add  |          1 |        1

-- Arbitrary query matches as rows.
SELECT * FROM ts_nodes('func A(){}', 'go', '(function_declaration) @f');

-- Discover what the worker can parse.
SELECT * FROM supported_languages();

