INSTALL vgi FROM community;
LOAD vgi;
ATTACH 'compress' (TYPE vgi, LOCATION 'github-auto://Query-farm/vgi-compress@v0.2.0');
SET search_path = 'compress.main';

-- 1. Decompress a column of gzip'd HTTP bodies in a log table.
SELECT request_id,
       decompress(body_gz, 'gzip')::VARCHAR AS body   -- BLOB -> BLOB, cast to text
FROM http_logs
WHERE detect_codec(body_gz) = 'gzip';

-- 2. Recompress a cold archive gzip -> zstd (transcode in place, no files).
UPDATE archive
SET payload = compress(decompress(payload, 'gzip'), 'zstd', 19),
    codec   = 'zstd';

-- 3. Auto-detect + decompress a mixed-codec Kafka payload column, with a bomb guard.
SELECT topic, partition, "offset",
       detect_codec(value)                 AS codec,
       decompress_auto(value, 67108864)    AS plaintext   -- cap 64 MiB/row
FROM kafka_messages;

-- 4. Compress a query result for export, and report the win.
SELECT compressed_size(blob, 'zstd', 19)   AS bytes_out,
       ratio(blob, 'zstd', 19)             AS ratio,   -- out/in, < 1.0 means it shrank
       compress(blob, 'zstd', 19)          AS packed
FROM (SELECT string_agg(line, '\n')::BLOB AS blob FROM report_lines);

INSTALL vgi FROM community;
LOAD vgi;
ATTACH 'cricket' (
  TYPE vgi,
  LOCATION 'uvx --from git+https://github.com/Query-farm/vgi-cricket@v0.1.0 vgi-cricket'
);

INSTALL vgi FROM community; LOAD vgi;

ATTACH 'cve' AS cve (TYPE vgi, LOCATION 'github-auto://Query-farm/vgi-cve@v0.2.1');

-- Offline CVSS math (no network):
SELECT cve.cvss_base_score('CVSS:3.1/AV:N/AC:L/PR:N/UI:N/S:U/C:H/I:H/A:H'); -- 9.8
SELECT cve.cvss_severity(9.8);                                              -- CRITICAL

-- Look up a CVE from the NVD API:
SELECT id, cvss_score, cvss_severity, cwe FROM cve.cve('CVE-2021-44228');

-- Keyword search (paginated, bounded to 100 results):
SELECT id, cvss_severity, published FROM cve.cve_search('log4j');

-- CVEs affecting a CPE name:
SELECT cve_id, cvss_score, cvss_severity
FROM cve.cpe_cves('cpe:2.3:a:apache:log4j:2.14.1:*:*:*:*:*:*:*');

INSTALL vgi FROM community;
LOAD vgi;

ATTACH 'disasm' AS disasm (TYPE vgi, LOCATION 'github-auto://Query-farm/vgi-disasm@v0.2.1');

-- Disassemble an x64 shellcode blob and project the instruction address, mnemonic, and
-- operands.
SELECT address, mnemonic, op_str FROM disasm.main.disassemble(from_hex('554889e5c3'), arch := 'x86', mode := 'x64');

-- Probe a blob by its magic bytes and read back just the detected container format.
SELECT (disasm.main.format(from_hex('7f454c46'))).container AS container;

INSTALL vgi FROM community; LOAD vgi;
ATTACH 'docgen' (TYPE vgi, LOCATION 'uvx --from git+https://github.com/Query-farm/vgi-docgen@v0.2.0 vgi-docgen');

-- One rendered DOCX per row (scalar): template + a STRUCT of row data -> BLOB
SELECT docgen.docgen_render('invoice.docx', {customer: name, total: amount})
FROM invoices;

-- Inline template bytes work too (BLOB template instead of a path)
SELECT docgen.docgen_render(tpl.bytes, {customer: name})
FROM letters, templates AS tpl;

-- Opt into PDF (3rd positional arg; requires headless LibreOffice on PATH)
SELECT docgen.docgen_render('invoice.docx', {total: amount}, true) FROM invoices;

-- Many rows -> ONE merged document (buffering): template as a NAMED arg
SELECT doc FROM docgen.docgen_merge(
    (SELECT customer, total FROM invoices),
    template := 'invoice.docx');

LOAD vgi;
ATTACH 'elasticsearch' AS es (TYPE vgi, LOCATION 'github-auto://Query-farm/vgi-elasticsearch@v0.2.1');

-- Page through an entire index as rows (columns derived from the mapping):
SELECT _id, name, n, created
FROM es.es_search('http://localhost:9200', 'my_index');

-- Predicates push to the cluster as a query DSL; only requested fields leave it:
SELECT _id, n
FROM es.es_search('http://localhost:9200', 'my_index')
WHERE n >= 100 AND status = 'active';

INSTALL vgi FROM community; LOAD vgi;
ATTACH 'embed' (TYPE vgi, LOCATION 'uvx --from git+https://github.com/Query-farm/vgi-embed@v0.2.0 vgi-embed-worker');

-- A 384-dimensional vector.
SELECT embed.embed('hello world');

-- Cosine similarity (pure, no model).
SELECT embed.similarity(embed.embed('cat'), embed.embed('kitten'));

-- Top-k semantic search over a column.
SELECT id, body
FROM docs
